{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_5_May2025 as WITH SKU_SUMMARY AS ( SELECT SKU_CODE, SUM(TOTAL_REPLEN_REQ) AS CUML_REPLEN_REQ, SUM(ALLOCATED_UNITS) AS CUML_ALLO FROM snitch_db.maplemonk.store_replen_4_May2025 GROUP BY SKU_CODE ), INTERIM_ALLO AS ( SELECT t.SKU_CODE, t.BRANCH_CODE, t.FINAL_ACTION, t.PARETO, t.PRIORITY, t.FACILITY, t.REPLEN_ORDER, t.TOTAL_REPLEN_REQ, t.ALLOCATED_UNITS, s.CUML_REPLEN_REQ, s.CUML_ALLO, CASE WHEN s.CUML_ALLO >= s.CUML_REPLEN_REQ THEN t.ALLOCATED_UNITS ELSE CEIL(s.CUML_ALLO * t.TOTAL_REPLEN_REQ / s.CUML_REPLEN_REQ) END AS INTERIM_ALLO FROM snitch_db.maplemonk.store_replen_4_May2025 t INNER JOIN SKU_SUMMARY s ON t.SKU_CODE = s.SKU_CODE ), SOCIALISTIC_ALLO AS ( SELECT i.*, CASE WHEN SUM(INTERIM_ALLO) OVER (PARTITION BY SKU_CODE ORDER BY REPLEN_ORDER ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) <= CUML_ALLO THEN INTERIM_ALLO ELSE 0 END AS SOCIALISTIC FROM INTERIM_ALLO i ) SELECT * FROM SOCIALISTIC_ALLO; create or replace table snitch_db.maplemonk.store_replen_6_May2025 as with Agg_JIT AS ( SELECT \"ITEM CODE\" AS SKU_CODE, BRANCH_CODE, SUM(QTY) AS total_jit_qty FROM SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS GROUP BY \"ITEM CODE\", BRANCH_CODE ), Agg_L AS ( SELECT ADDLITEMCODE AS SKU_CODE, BRANCH_CODE, SUM(STOCK_QTY) AS total_stock_qty FROM SNITCH_DB.MAPLEMONK.LOGICERP23_24_GET_STOCK_IN_HAND WHERE DATE = CURRENT_DATE GROUP BY ADDLITEMCODE, BRANCH_CODE ) SELECT S5.* FROM SNITCH_DB.MAPLEMONK.store_replen_5_May2025 S5 JOIN SNITCH_DB.MAPLEMONK.store_replen_2_May2025 S2 ON S5.SKU_CODE = S2.logicusercode AND S5.BRANCH_CODE = S2.BRANCH_CODE LEFT JOIN Agg_L L ON S5.SKU_CODE = L.SKU_CODE AND S5.BRANCH_CODE = L.BRANCH_CODE LEFT JOIN Agg_JIT J ON S5.SKU_CODE = J.SKU_CODE AND S5.BRANCH_CODE = J.BRANCH_CODE WHERE NOT (S2.FINAL_ROS < 0.6 AND (S5.SOCIALISTIC + COALESCE(L.total_stock_qty, 0) + COALESCE(J.total_jit_qty, 0)) > 6); create or replace table snitch_db.maplemonk.store_replen_6_Nov2025 as with Agg_JIT AS ( SELECT \"ITEM CODE\" AS SKU_CODE, BRANCH_CODE, SUM(QTY) AS total_jit_qty FROM SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS GROUP BY \"ITEM CODE\", BRANCH_CODE ), Agg_L AS ( SELECT ADDLITEMCODE AS SKU_CODE, BRANCH_CODE, SUM(STOCK_QTY) AS total_stock_qty FROM SNITCH_DB.MAPLEMONK.LOGICERP23_24_GET_STOCK_IN_HAND WHERE DATE = CURRENT_DATE GROUP BY ADDLITEMCODE, BRANCH_CODE ) SELECT S4.* FROM SNITCH_DB.MAPLEMONK.store_replen_4_Nov2025 S4 JOIN SNITCH_DB.MAPLEMONK.store_replen_2_May2025 S2 ON S4.SKU_CODE = S2.logicusercode AND S4.BRANCH_CODE = S2.BRANCH_CODE LEFT JOIN Agg_L L ON S4.SKU_CODE = L.SKU_CODE AND S4.BRANCH_CODE = L.BRANCH_CODE LEFT JOIN Agg_JIT J ON S4.SKU_CODE = J.SKU_CODE AND S4.BRANCH_CODE = J.BRANCH_CODE WHERE NOT (S2.FINAL_ROS < 0.6 AND (S4.ALLOCATED_UNITS + COALESCE(L.total_stock_qty, 0) + COALESCE(J.total_jit_qty, 0)) > 6) ; CREATE OR REPLACE TABLE snitch_db.maplemonk.SRU_RPL_5_MARCH_26 AS with inv_base_pivot as ( select * from snitch_db.maplemonk.SRU_RPL_3_MARCH_26 ), rpl_output_pivot as ( SELECT branch_code, sku_group, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'XS\',\'28\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_xs, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'S\',\'30\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_s, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'M\',\'32\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_m, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'L\',\'34\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_l, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'XL\',\'36\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'XXL\',\'38\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_xxl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'3XL\',\'40\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_3xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'4XL\',\'42\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_4xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'5XL\',\'44\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_5xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'6XL\',\'46\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_6xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'7XL\',\'48\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_7xl, SUM(CASE WHEN CAST(sizes_mapped AS STRING) IN (\'8XL\',\'50\') THEN SOCIALISTIC_ALLOCATED_UNITS ELSE 0 END) AS rpl_8xl from snitch_db.maplemonk.SRU_RPL_4_MARCH_26 GROUP BY 1, 2 ), joined as( select a.BRANCH_CODE, a.SKU_GROUP, a.CATEGORY, a.INV_XS, a.INV_S, a.INV_M, a.INV_L, a.INV_XL, a.INV_XXL, a.INV_3XL, a.INV_4XL, a.INV_5XL, a.INV_6XL, a.INV_7XL, a.INV_8XL, a.JIT_XS, a.JIT_S, a.JIT_M, a.JIT_L, a.JIT_XL, a.JIT_XXL, a.JIT_3XL, a.JIT_4XL, a.JIT_5XL, a.JIT_6XL, a.JIT_7XL, a.JIT_8XL, b.RPL_XS, b.RPL_S, b.RPL_M, b.RPL_L, b.RPL_XL, b.RPL_XXL, b.RPL_3XL, b.RPL_4XL, b.RPL_5XL, b.RPL_6XL, COALESCE(a.INV_XS,0) + COALESCE(a.JIT_XS,0) + COALESCE(b.RPL_XS,0) AS TTL_XS, COALESCE(a.INV_S,0) + COALESCE(a.JIT_S,0) + COALESCE(b.RPL_S,0) AS TTL_S, COALESCE(a.INV_M,0) + COALESCE(a.JIT_M,0) + COALESCE(b.RPL_M,0) AS TTL_M, COALESCE(a.INV_L,0) + COALESCE(a.JIT_L,0) + COALESCE(b.RPL_L,0) AS TTL_L, COALESCE(a.INV_XL,0) + COALESCE(a.JIT_XL,0) + COALESCE(b.RPL_XL,0) AS TTL_XL, COALESCE(a.INV_XXL,0) + COALESCE(a.JIT_XXL,0) + COALESCE(b.RPL_XXL,0) AS TTL_XXL, COALESCE(a.INV_3XL,0) + COALESCE(a.JIT_3XL,0) + COALESCE(b.RPL_3XL,0) AS TTL_3XL, COALESCE(a.INV_4XL,0) + COALESCE(a.JIT_4XL,0) + COALESCE(b.RPL_4XL,0) AS TTL_4XL, COALESCE(a.INV_5XL,0) + COALESCE(a.JIT_5XL,0) + COALESCE(b.RPL_5XL,0) AS TTL_5XL, COALESCE(a.INV_6XL,0) + COALESCE(a.JIT_6XL,0) + COALESCE(b.RPL_6XL,0) AS TTL_6XL, COALESCE(a.INV_7XL,0) + COALESCE(a.JIT_7XL,0) + COALESCE(b.RPL_7XL,0) AS TTL_7XL, COALESCE(a.INV_8XL,0) + COALESCE(a.JIT_8XL,0) + COALESCE(b.RPL_8XL,0) AS TTL_8XL from inv_base_pivot a left join rpl_output_pivot b on a.branch_code = b.branch_code and a.sku_group = b.sku_group ), replen_remarks as ( select *, CASE WHEN branch_code in (139, 155, 146, 123, 120, 157, 154, 152, 104) then \'Yes\' WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' and ( (case when ttl_xs > 0 then 1 else 0 end) + (case when ttl_s > 0 then 1 else 0 end) + (case when ttl_m > 0 then 1 else 0 end) + (case when ttl_l > 0 then 1 else 0 end) + (case when ttl_xl > 0 then 1 else 0 end) + (case when ttl_xxl > 0 then 1 else 0 end) + (case when ttl_3xl > 0 then 1 else 0 end) + (case when ttl_4xl > 0 then 1 else 0 end) + (case when ttl_5xl > 0 then 1 else 0 end) + (case when ttl_6xl > 0 then 1 else 0 end) + (case when ttl_7xl > 0 then 1 else 0 end) + (case when ttl_8xl > 0 then 1 else 0 end) ) >= 3 then \'Yes\' WHEN UPPER(SKU_GROUP) not LIKE \'4MBG%\' OR UPPER(SKU_GROUP) not LIKE \'4BRN%\' OR UPPER(SKU_GROUP) not LIKE \'4BPL%\' OR UPPER(SKU_GROUP) not LIKE \'4BTR%\' OR UPPER(SKU_GROUP) not LIKE \'4BCH%\' OR UPPER(SKU_GROUP) not LIKE \'4BJE%\' OR UPPER(SKU_GROUP) not LIKE \'4BJK%\' OR UPPER(SKU_GROUP) not LIKE \'4BSW%\' OR UPPER(SKU_GROUP) not LIKE \'4BHD%\' OR UPPER(SKU_GROUP) not LIKE \'4BOS%\' OR UPPER(SKU_GROUP) not LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) not LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) not LIKE \'4BSH%\' OR UPPER(SKU_GROUP) not LIKE \'4BBL%\' OR UPPER(SKU_GROUP) not LIKE \'4BCA%\' OR UPPER(SKU_GROUP) not LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) not LIKE \'4BCD%\' OR UPPER(SKU_GROUP) not LIKE \'4BJO%\' and ( (case when ttl_xs > 0 then 1 else 0 end) + (case when ttl_s > 0 then 1 else 0 end) + (case when ttl_m > 0 then 1 else 0 end) + (case when ttl_l > 0 then 1 else 0 end) + (case when ttl_xl > 0 then 1 else 0 end) + (case when ttl_xxl > 0 then 1 else 0 end) + (case when ttl_3xl > 0 then 1 else 0 end) + (case when ttl_4xl > 0 then 1 else 0 end) + (case when ttl_5xl > 0 then 1 else 0 end) + (case when ttl_6xl > 0 then 1 else 0 end) ) >= 4 then \'Yes\' else \'No\' end as replen_flag from joined), unpivot_with_remarks AS ( SELECT * from replen_remarks where replen_flag = \'Yes\' ), initial_replen_output as ( select * from snitch_db.maplemonk.SRU_RPL_4_MARCH_26 ), filtered_initial_replen_output as ( select i.* from initial_replen_output i inner join ( select distinct branch_code, sku_group from unpivot_with_remarks ) r on i.branch_code = r.branch_code and i.sku_group = r.sku_group ) select * from filtered_initial_replen_output; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SRU_RPL_6_AUG_26 AS with replen_5_output as ( select *, case when SIZES_MAPPED in (\'28\', \'38\', \'40\', \'42\', \'44\', \'46\', \'48\', \'XS\', \'XXL\', \'3XL\', \'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN LEAST(SOCIALISTIC_ALLOCATED_UNITS, 3) when SIZES_MAPPED in (\'30\', \'32\', \'34\', \'36\', \'S\', \'M\', \'L\', \'XL\') THEN LEAST(6,SOCIALISTIC_ALLOCATED_UNITS) ELSE SOCIALISTIC_ALLOCATED_UNITS END AS REPLEN_QTY from snitch_db.maplemonk.SRU_RPL_5_MARCH_26 QUALIFY ROW_NUMBER() OVER ( PARTITION BY SKU, branch_code, facility ORDER BY allocated_units DESC ) = 1 UNION ALL SELECT BRANCH_CODE, SKU_GROUP, COALESCE(SIZE_SKU_CODE, SKU_GROUP) AS SKU, COALESCE(PRODUCT_SIZE, \'NA\') AS SIZES_MAPPED, STORE_SELL_THROUGH AS AVG_SKU_SELL_THRU, REPLEN_PRIORITY_BUCKET AS FINAL_RANK, ALLOCATED_QTY AS REPLEN_UNITS, ALLOCATED_QTY AS ALLOCATED_UNITS, REGION AS ZONE, WAREHOUSE_NAME AS FACILITY, ALLOCATED_QTY AS SOCIALISTIC_ALLOCATED_UNITS, CASE WHEN CATEGORY = \'SHOES\' AND PRODUCT_SIZE IN (\'40\', \'45\', \'46\') THEN LEAST(ALLOCATED_QTY, 3) WHEN CATEGORY = \'SHOES\' AND PRODUCT_SIZE IN (\'41\', \'42\', \'43\', \'44\') THEN LEAST(6, ALLOCATED_QTY) WHEN CATEGORY = \'BELTS\' AND PRODUCT_SIZE IN (\'28\', \'30\', \'34\', \'38\') THEN LEAST(ALLOCATED_QTY, 3) WHEN CATEGORY = \'BELTS\' AND PRODUCT_SIZE IN (\'32\', \'36\', \'40\') THEN LEAST(6, ALLOCATED_QTY) ELSE ALLOCATED_QTY END AS REPLEN_QTY FROM snitch_db.maplemonk.OFFLINE_LONG_TAIL_REPLEN_7_26 ), MAX_ORDER_NUM AS ( SELECT MAX(upper(trim(RIGHT(order_name, 5)))) AS order_name_max FROM ( SELECT * FROM snitch_db.maplemonk.b2b_journey WHERE order_DATE is not null AND order_date >= \'2026-07-25\' and RIGHT(order_name, 5) not in (\'D1115\',\'A1115\',\'R1115\',\'I1115\',\'M1264\',\'A1264\',\'R1264\',\'N1264\', \'I1265\', \'A1265\',\'R1265\',\'M1265\',\'N1265\',\'N1260\',\'B1260\') AND order_name not like \'%QC-%\' ) ), STORE_DETAILS_UC AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.UC_IMPORT ), COST_PRICE_MAPPING AS ( SELECT sku, MAX(cost_price) AS cost_price FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER GROUP BY 1 ), SO_number_prep AS ( SELECT r.*, LPAD( TO_VARCHAR( COALESCE(m.order_name_max, 0) + CASE r.facility WHEN \'SAPL-WH2\' THEN 10 WHEN \'SAPL-WH1\' THEN 11 WHEN \'SAPL-NORTH-TAURU\' THEN 12 ELSE 0 END ), 5, \'0\' ) AS so_number_5d FROM replen_5_output r CROSS JOIN MAX_ORDER_NUM m ), store_details_join AS ( SELECT p.*, uc.\"Short Name\", uc.\"Store Name\" as store_name, CONCAT(COALESCE(LEFT(uc.\"Short Name\", 6),\'\'), COALESCE(p.so_number_5d, \'\')) AS so_number, CASE WHEN UPPER(TRIM(uc.\"Store Name\")) LIKE \'%FOCO%\' THEN cosp.cost_price * 1.25 ELSE cosp.cost_price END AS cost_price FROM SO_number_prep p LEFT JOIN STORE_DETAILS_UC uc ON p.branch_code = uc.\"STORE CODE\" LEFT JOIN COST_PRICE_MAPPING cosp ON LOWER(TRIM(p.sku)) = LOWER(TRIM(cosp.sku)) ), store_details_join_seq AS ( SELECT sdj.*, ROW_NUMBER() OVER ( PARTITION BY sdj.so_number ORDER BY sdj.sku, sdj.branch_code, sdj.facility ) AS item_seq FROM store_details_join sdj ), FINAL_OUTPUT AS ( select sdj.SO_NUMBER AS \"Sales Order Code*\", sdj.SO_NUMBER AS \"Display Sales Order Code\", uc.\"EMAIL ID\" AS \"Notification Email\", NULL AS \"Notification Mobile\", 1 AS \"COD*\", uc.CHANNEL AS \"Channel\", NULL AS \"Priority\", uc.\"STORE CODE\" AS \"Shipping Address Id\", uc.\"Shipping Address Name\" AS \"Shipping Address Name\", uc.\"Shipping Address Line 2\" AS \"Shipping Address Line 1\", uc.\"COMPANY NAME\" AS \"Shipping Address Line 2\", uc.\"Shipping Address City\" AS \"Shipping Address City\", uc.\"Shipping Address State\" AS \"Shipping Address State\", uc.\"Shipping Address Country\" AS \"Shipping Address Country\", uc.\"Shipping Address Pincode\" AS \"Shipping Address Pincode\", NULL AS \"Shipping Address Latitude\", NULL AS \"Shipping Address Longitude\", uc.\"Shipping Address Phone\" AS \"Shipping Address Phone\", uc.\"Billing Address Id\" AS \"Billing Address Id\", uc.\"Billing Address Name\" AS \"Billing Address Name\", uc.\"Billing Address Line 1\" AS \"Billing Address Line 1\", uc.\"Billing Address Line 2\" AS \"Billing Address Line 2\", uc.\"Billing Address City\" AS \"Billing Address City\", uc.\"Billing Address State\" AS \"Billing Address State\", \'IN\' AS \"Billing Address Country\", uc.\"Billing Address Pincode\" AS \"Billing Address Pincode\", NULL AS \"Billing Address Latitude\", NULL AS \"Billing Address Longitude\", uc.\"Billing Address Phone\" AS \"Billing Address Phone\", NULL AS \"Combination Identifier\", NULL AS \"Combination Description\", CONCAT(sdj.so_number, sdj.item_seq) AS \"Sale Order Item Code*\", \'STD\' AS \"Shipping Method*\", sdj.SKU AS \"Item SKU Code*\", NULL AS \"Channel Product Id\", NULL AS \"Item Name\", NULL AS \"Requires Customization\", NULL AS \"Gift Wrap\", NULL AS \"Gift Message*\", sdj.COST_PRICE AS \"Selling Price\", 0 AS \"Discount\", 0 AS \"Shipping Charges\", NULL AS \"Shipping Method Charges\", NULL AS \"COD Service Charges\", NULL AS \"Gift Wrap Charges\", NULL AS \"Voucher Code\", NULL AS \"Voucher Value\", NULL AS \"Store Credit\", NULL AS \"Packet Number\", NULL AS \"On Hold\", NULL AS \"Order Date as dd/mm/yyyy hh:MM:ss\", NULL AS \"Channel Order Processing Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Shipping Provider\", NULL AS \"Tracking Number\", sdj.REPLEN_QTY AS \"Quantity\", NULL AS \"Quantity In Combo\", NULL AS \"Prepaid Amount\", NULL AS \"Customer Code\", NULL AS \"Currency Code\", NULL AS \"Customer GSTIN\", NULL AS \"Order Total Shipping Charges\", TO_CHAR(DATEADD(\'hour\', 16, DATEADD(\'day\', 2, CURRENT_DATE()::timestamp_ntz)),\'DD-MM-YYYY HH:MI AM\') AS \"Fulfillment Tat\", NULL AS \"Shipping Package Type Code\", NULL AS \"Transaction Id\", NULL AS \"Transaction Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Amount Paid\", NULL AS \"Payment Mode\", NULL AS \"Transaction Note\", sdj.FACILITY AS \"Facility Code\", sdj.SO_NUMBER AS \"Parent Sale Order Code\", NULL AS \"Item Tag\", NULL AS \"CHANNEL_ORDER_NUMBER\", uc.DISCOUNTCODE AS \"DiscountCode\", uc.\"ACC CODE\" AS \"GiftMessage\", \'RPL\' AS \"Order_Type\", CASE WHEN UPPER(TRIM(\"Facility Code\")) = \'SAPL-NORTH-TAURU\' AND UPPER(TRIM(\"Shipping Address State\")) = \'HARYANA\' THEN \'ST\' WHEN UPPER(TRIM(\"Facility Code\")) IN (\'SAPL-WH1\', \'SAPL-WH2\') AND UPPER(TRIM(\"Shipping Address State\")) = \'KARNATAKA\' THEN \'ST\' ELSE \'WS\' END AS \"SaleInvoicePrefix\", NULL AS \"ShopifyTags\", NULL AS \"SnitchOnline\", sdj.BRANCH_CODE AS \"STORE-CODE*\" FROM store_details_join_seq sdj LEFT JOIN STORE_DETAILS_UC uc ON sdj.branch_code = uc.\"STORE CODE\" ), SO_FILTER AS ( SELECT \"Sales Order Code*\", SUM(\"Quantity\") AS total_qty FROM FINAL_OUTPUT GROUP BY 1 HAVING SUM(\"Quantity\") >= 15 ) SELECT * FROM FINAL_OUTPUT WHERE \"Sales Order Code*\" IN (SELECT \"Sales Order Code*\" FROM SO_FILTER) ORDER BY \"STORE-CODE*\", \"Facility Code\" ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

